+    fn reclamation_clean_eviction_keeps_sparse_dirty_pages_until_publication() {
+        use crate::common::disk::{fsync_counts, SITE_BPLUS_PAGE_FLUSH};
+        for reference in [true, false] {
+            let path = crate::common::ScratchPath::new("page", "clean_reclamation", ".db");
