+                pm.begin_reclamation().unwrap();
+                for i in 1..=10u64 { assert!(pm.write_page(PageId(i), &(i + 1000).to_le_bytes())); }
+                assert!(pm.free_page(PageId(257)));
+                pm.max_cache_pages = 256;
